let lastJob=null,catalog,banks,view='library',selection=new Set(),focusId=null,kind='all',query='',collection='all',trash=false,bankIndex=0,bankSlot=0,unitSlots=null,unitProjects=null,unitBackup=null,restoreFile=null,inspection=null,activeJob=false,busy=false,bundledFirmware=[];
const notify=s=>$('#notice').textContent=s, fail=e=>{if(!e.presented)$('#failure').textContent=e.message||String(e);};
async function api(path,data){const r=await fetch(path,data?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}:{});const body=await r.json();if(!r.ok){const e=Error(body.error||'Request failed');e.status=r.status;throw e;}return body;}
const run=fn=>async(...args)=>{if(busy)return;busy=true;$('#failure').textContent='';try{await fn(...args);}catch(e){fail(e);}finally{busy=false;}};
