 if(item){if($('#extractSounds'))bind('#extractSounds',()=>mutate('extract',{id:item.id}));bind('#saveDetails',async()=>{const edited=structuredClone(item.entry);const state=(await api('/api/work',{action:'decode',entry:edited})).state;edited.name=$('#itemName').value.trim();state.vced.splice(145,10,...edited.name.padEnd(10,' ').split('').map(c=>c.charCodeAt(0)));const result=await api('/api/work',{action:'encode',entry:edited,state});await mutate('update',{id:item.id,title:$('#itemTitle').value,collection:$('#itemCollection').value,tags:$('#itemTags').value.split(',').map(s=>s.trim()).filter(Boolean),notes:$('#itemNotes').value,favorite:$('#itemFavorite').checked,entry:result.entry});notify('Library details saved. Device unchanged.');});bind('#openItem',async()=>{await openEditor(item.entry);});bind('#sendItem',()=>reviewTransfers([{kind:item.kind,slot:0,entry:item.entry}]));if($('#sendBundle'))bind('#sendBundle',()=>reviewTransfers([...Object.entries(item.dependencies).map(([slot,entry])=>({kind:'instrument',slot:Number(slot),entry})),{kind:'project',slot:0,entry:item.entry}]));}
