async function reviewTransfers(rows){
 if(!rows.length)throw Error('Select populated sounds or projects first.');
 if(rows.length>144)throw Error('Select no more than 128 instruments and 16 projects per transfer.');
 const dialog=$('#transfer');
 $('#transferRows').innerHTML=`<table><thead><tr><th>Sound / project</th><th>Destination on FM-1</th></tr></thead><tbody>${rows.map((r,i)=>`<tr><td>${esc(r.entry.name)}<small>${r.kind==='project'?'Project record; references instrument slots':'Instrument'}</small></td><td><select data-transfer="${i}" aria-label="Destination for ${esc(r.entry.name)}">${Array.from({length:r.kind==='project'?16:128},(_,n)=>option(n,r.kind==='project'?'Project '+String(n).padStart(2,'0'):unitLabel(n),r.slot)).join('')}</select></td></tr>`).join('')}</tbody></table>`;
 if(rows.every(r=>r.kind==='instrument')&&rows.length<=64){
  $('#transferRows').insertAdjacentHTML('afterbegin',`<div class="bar"><label>Place in<select id="transferBank">${option(0,'Bank B',rows[0].slot<64?0:64)}${option(64,'Bank A',rows[0].slot<64?0:64)}</select></label><label>Starting slot<select id="transferStart">${Array.from({length:65-rows.length},(_,n)=>option(n,String(n).padStart(2,'0'),0)).join('')}</select></label><button type="button" id="placeTransfer">Place consecutively</button></div>`);
  $('#placeTransfer').onclick=()=>{const start=Number($('#transferBank').value)+Number($('#transferStart').value);rows.forEach((r,i)=>{$(`[data-transfer="${i}"]`).value=String(start+i);});};
 }
 const response=await new Promise(resolve=>{dialog.addEventListener('close',()=>resolve(dialog.returnValue),{once:true});dialog.showModal();});
 if(response!=='review')return;
 const selected=rows.map((r,i)=>({...r,slot:Number($(`[data-transfer="${i}"]`).value)}));
 const plan=await api('/api/transfer-plan',{rows:selected});
 if(!await confirmAction(`Replace ${plan.count} unit slot${plan.count===1?'':'s'}?`,plan.rows.map(r=>r.destination+' ← '+r.name).join('\n')+'\n\n'+plan.scope))return;
 const result=await deviceJob({action:'deploy_library',rows:selected,confirmation:plan.confirmation});
 if(result.backup){unitBackup=result.backup;jsonDownload('FMER-before-library-transfer.fmer-backup.json',unitBackup);}
 notify(`${plan.count} slots verified. The pre-transfer backup was downloaded. Playback is stopped.`);
}
function editorAPI(){const e=$('#editor').contentWindow.fmerLibrary;if(!e?.ready())throw Error('The editor is still loading; try again in a moment');return e;}
async function openEditor(entry){changeView('editor');notify('Opening sound editor?');const deadline=Date.now()+30000;while(!$('#editor').contentWindow.fmerLibrary?.ready()){if(Date.now()>deadline)throw Error('The sound editor did not finish opening. Reload the workspace and try again; saved sounds are unchanged.');await new Promise(resolve=>setTimeout(resolve,50));}await editorAPI().open(entry);notify('Sound opened in the editor. Saved banks are unchanged.');}
async function importLibrary(file){if(file.name.endsWith('.fmer-native')){const raw=await file.arrayBuffer();const result=await api('/api/work',{action:'import',raw:btoa(String.fromCharCode(...new Uint8Array(raw)))});await mutate('add',{kind:'project',title:result.entry.name,entry:result.entry,collection:'Imported',notes:'Native file: referenced instrument snapshots are not embedded.'});}else {const backup=JSON.parse(await file.text());await mutate(backup.format==='FMER-SOUNDBANK-FILE'?'import_banks':'import',{backup});}notify('Imported into the local Library. No unit changes.');}
bind('#captureEditor',async()=>{const entry=await editorAPI().capture(),kind=$('#captureKind').value;const dependencies={};if(kind==='project'){banks=await api('/api/banks');const state=(await api('/api/work',{action:'decode',entry})).state;for(const t of state.tracks){const value=banks.slots[(t.sound_ref+64)%128];if(value)dependencies[String(t.sound_ref)]=value;}}catalog=await api('/api/catalog',{action:'add',revision:catalog.revision,kind,title:entry.name,entry,dependencies,notes:kind==='project'?'Embedded sounds copied from PC bank references at capture time. Reconcile PC and unit banks before deploying.':''});focusId=catalog.slots.at(-1).id;changeView('library');notify('Saved a new Library copy. Existing bank slots unchanged.');});
function drawBanks(){const selected=banks.slots[bankSlot];$('#content').innerHTML=`<div class="panel"><h2>PC sound banks</h2><p>These two editable banks live on this computer. Bank A and Bank B on the FM-1 are separate until you send a sound. ${help('banks')}</p><div class="bar"><select id="pcBank" aria-label="PC bank">${option(0,'FMER Defaults · 64',bankIndex)}${option(1,'User · 64',bankIndex)}</select><select id="pcSlot" aria-label="PC sound slot">${banks.slots.slice(bankIndex*64,bankIndex*64+64).map((e,i)=>option(i+bankIndex*64,String(i).padStart(2,'0')+' · '+(e?.name||'Empty'),bankSlot)).join('')}</select><button id="refreshPC">Refresh</button></div><div class="cards"><div><h3>${esc(selected?.name||'Empty slot')}</h3><p>${esc(selected?.category||'Choose an occupied slot to edit or archive.')}</p><div class="bar"><button id="bankEdit" ${selected?'':'disabled'} class="primary">Open editor</button><button id="bankSend" ${selected?'':'disabled'}>Send sound to unit&hellip;</button><button id="bankArchive" ${selected?'':'disabled'}>Add to Library</button></div><label>Instrument name <input id="bankName" maxlength="10" value="${esc(selected?.name||'')}"></label><button id="bankRename" ${selected?'':'disabled'}>Rename</button></div><div><label>Destination<select id="bankDestination" aria-label="PC bank destination">${banks.slots.map((e,i)=>option(i,pcLabel(i)+' · '+(e?.name||'Empty'),(bankSlot+1)%128)).join('')}</select></label><div class="bar"><button id="bankCopy" ${selected?'':'disabled'}>Copy…</button><button id="bankMove" ${selected&&bankSlot>=64?'':'disabled'}>Move to empty</button><button id="bankSwap" ${selected?'':'disabled'}>Swap</button><button id="bankDelete" class="danger" ${selected&&bankSlot>=64?'':'disabled'}>Clear slot</button></div><p class="muted">Bank A stays populated. Move needs an empty destination; Swap retains both sounds. Projects still reference slot numbers, so review assignments after rearranging.</p></div></div><div class="bar"><button id="undoBank" ${banks.can_undo?'':'disabled'}>Undo bank change</button><button id="sendBank" class="primary">Send this bank to unit&hellip;</button><button id="backupBanks">Export both PC banks</button><button id="restoreBanks">Restore PC banks…</button></div></div><div class="panel"><h2>Independent bank resets</h2><p>Each action applies to the selected scope only. These controls change PC banks, not the unit.</p><div class="bar"><button data-reset="reset_defaults">Reset Bank A</button><button data-reset="reset_user">Reset Bank B</button><button data-reset="clear_user" class="danger">Clear Bank B</button></div></div>`;
 $('#pcBank').onchange=e=>{bankIndex=Number(e.target.value);bankSlot=bankIndex*64;drawBanks();};$('#pcSlot').onchange=e=>{bankSlot=Number(e.target.value);drawBanks();};bind('#refreshPC',async()=>{banks=await api('/api/banks');drawBanks();});bind('#bankEdit',async()=>{await openEditor(selected);});bind('#bankArchive',async()=>{catalog=await api('/api/catalog',{action:'add',revision:catalog.revision,kind:'instrument',title:selected.name,entry:selected,collection:'From PC banks'});notify('Saved to Library.');});
 async function bankAction(action,data={}){banks=await api('/api/banks',{action,slot:bankSlot,revision:banks.revision,...data});drawBanks();notify('PC bank updated. Unit unchanged.');}
 bind('#bankSend',()=>reviewTransfers([{kind:'instrument',slot:(bankSlot+64)%128,entry:selected}]));bind('#sendBank',()=>reviewTransfers(banks.slots.map((entry,i)=>({kind:'instrument',slot:(i+64)%128,entry,pc:i})).filter(r=>r.entry&&Math.floor(r.pc/64)===bankIndex).map(({pc,...r})=>r)));bind('#bankRename',()=>bankAction('rename',{name:$('#bankName').value.trim()}));for(const [id,action] of [['#bankCopy','copy'],['#bankMove','move'],['#bankSwap','swap']])bind(id,async()=>{const destination=Number($('#bankDestination').value);if(await confirmAction(`${action} ${pcLabel(bankSlot)}?`,`Destination: ${pcLabel(destination)}. Copy replaces its contents. Move requires an empty slot. Swap exchanges both. Project references are not remapped.`))await bankAction(action,{destination});});bind('#bankDelete',()=>bankAction('delete'));bind('#undoBank',()=>bankAction('undo'));bind('#backupBanks',async()=>jsonDownload('FMER-PC-banks.json',(await api('/api/banks',{action:'backup'})).backup));bind('#restoreBanks',()=>chooseFile('.json',async f=>{const backup=JSON.parse(await f.text());if(await confirmAction('Restore both PC banks?','This replaces all128 PC slots. Undo remains available. The unit is unchanged.'))await bankAction('restore',{backup});}));document.querySelectorAll('[data-reset]').forEach(b=>b.onclick=run(async()=>{if(await confirmAction(b.textContent,b.dataset.reset==='clear_user'?'Empty all 64 slots in PC Bank B. Bank A remains intact.':'Restore original copies only in the named PC bank. The other bank remains intact.'))await bankAction(b.dataset.reset,{confirmation:({reset_defaults:"Reset to FMER Default",reset_user:"Reset User Bank",clear_user:"Clear User Bank"})[b.dataset.reset||b.dataset.unitReset]});}));
}
async function deviceJob(request){if(activeJob)throw Error('Wait for the current device operation');const job=await api('/api/jobs',unitRequest({action:'device',request}));return await waitJob(job.id);}
function connectionLabel(identity){return identity?.startsWith('ota-')?'FM-1 updater':['FM-1_733','FM-1_734','FM-1_735'].includes(identity)?'FMER connected':identity?identity.replace('FM-1_','FM-1 \u00b7 firmware ')+' connected':'Check connection';}
function operationBusy(on){$('#content').inert=on;$('#editorPane').inert=on;$('#quitApp').disabled=on;$('#connection').disabled=on;$('#namedUnitSelect').disabled=on;}
async function waitJob(id){
 activeJob=true;operationBusy(true);$('#jobOutcome').hidden=true;$('#downloadJob').hidden=true;$('#downloadJobBackup').hidden=true;sessionStorage.setItem('fmerJob',id);$('#operation').hidden=false;$('#operation').dataset.state='running';$('#jobSafety').textContent='Keep the unit powered on and USB connected. Leave its controls untouched until completion.';$('#jobProgress').removeAttribute('value');$('#jobCount').textContent='';
 for(;;){
  let job;try{job=await api('/api/jobs/'+id);}catch(e){if(e.status===404){sessionStorage.removeItem('fmerJob');activeJob=false;operationBusy(false);invalidateUnit('Operation record unavailable - check connection');throw e;}$('#jobMessage').textContent='Reconnecting to companion...';$('#jobSafety').textContent='The operation may still be running. Keep the unit connected.';await new Promise(r=>setTimeout(r,1200));continue;}
  $('#jobMessage').textContent=job.message+(job.state!=='running'?' (last operation: '+new Date(job.finished||job.created).toLocaleTimeString()+')':'');
  if(job.identity)$('#connection').textContent=connectionLabel(job.identity);
  const p=job.progress||{},bar=$('#jobProgress');
  if(Number.isFinite(p.done)&&p.total>0){bar.max=p.total;bar.value=p.done;$('#jobCount').textContent=Math.floor(100*p.done/p.total)+'% \u00b7 '+p.done.toLocaleString()+' / '+p.total.toLocaleString()+' '+(p.unit||'');}else{bar.removeAttribute('value');$('#jobCount').textContent='Working...';}
  $('#jobElapsed').textContent='Elapsed '+Math.max(0,Math.floor((Date.now()-Date.parse(job.created))/1000))+' seconds';
  if(job.state!=='running'){
   lastJob=job;$('#downloadJobBackup').hidden=!(job.backup_path||job.progress?.backup_path);$('#jobRecord').hidden=false;$('#downloadJob').hidden=false;$('#jobDetails').textContent=JSON.stringify(job,null,2);sessionStorage.removeItem('fmerJob');activeJob=false;operationBusy(false);$('#operation').dataset.state=job.state;
   if(job.state!=='complete'){
    invalidateUnit('Connection unverified - check again');
    const outcome=job.outcome||{title:'The operation could not finish',explanation:'The operation was not completed.',next_step:'Export the operation record for diagnosis.'};
    $('#jobOutcome').hidden=false;$('#jobReason').textContent=outcome.title;$('#jobExplanation').textContent=outcome.explanation;$('#jobNext').textContent=outcome.next_step;
    $('#jobMessage').textContent='Operation stopped';$('#jobSafety').textContent='Read the explanation and next step here. Technical details are optional.';$('#jobCount').textContent='Not completed';
    const error=Error(outcome.title);error.presented=true;throw error;
   }
   bar.max=1;bar.value=1;$('#jobCount').textContent='Complete';$('#jobSafety').textContent='You can use the instrument again.';
   if(job.result?.identity||job.result?.firmware)$('#connection').textContent=connectionLabel(job.result.identity||job.result.firmware);
   if(job.operation!=='probe'){unitSlots=null;unitProjects=null;if(view==='unit')drawUnit();}notify('Operation complete.');return job.result;
  }
  await new Promise(r=>setTimeout(r,300));
 }
}
bind('#connection',async()=>{const r=await deviceJob({action:'probe'});$('#connection').textContent=connectionLabel(r.identity);if(!r.can_manage)notify(r.community_capture?`${r.community.family} detected. Use Library / Included & community sounds to read FM voices. Native projects and firmware switching are not supported.`:'FM-1 detected. Open Firmware to install FMER; stock firmware does not provide library or backup commands.');});
function itemOptions(){return catalog.slots.filter(i=>!i.trashed).map(i=>option(i.id,`${i.kind} · ${i.title}`,'')).join('');}
function drawUnit(){
 $('#content').innerHTML=`<div class="panel"><h2>Connect when you are ready</h2><p>Power on one FM-1 and connect USB. For companion operations, leave only the instrument you want to manage connected. FMER733–735 is required for library operations. Close other applications that own its MIDI ports. Reading a catalog is passive; loads and writes stop playback. ${help('connection')}</p><div class="bar"><button id="readUnit" class="primary">Read instrument banks</button><button id="readProjects">Read projects</button><button id="unitRecordStop">Release MIDI for music apps</button></div><details><summary>Diagnostics &amp; session logs</summary><div class="bar"><button id="unitRecord">Start diagnostic capture</button><button id="batteryHistory">Download battery history</button></div></details><div></div></div><div class="cards"><section class="panel"><h2>Unit instruments</h2><select id="unitSlot" aria-label="Unit instrument slot">${Array.from({length:128},(_,i)=>option(i,unitLabel(i)+(unitSlots?' · '+(unitSlots[i]?.name||'Empty'):''),0)).join('')}</select><div class="bar"><button id="pullInstrument">Add to Library</button><button id="playInstrument">Load on unit…</button></div><label>Rename <input id="unitName" maxlength="10" aria-label="New unit instrument name" value="${esc(unitSlots?.[0]?.name||'')}"></label><button id="renameUnit">Apply rename…</button><label>Destination<select id="unitDestination" aria-label="Unit copy destination">${Array.from({length:128},(_,i)=>option(i,unitLabel(i),1)).join('')}</select></label><div class="bar"><button id="copyUnit">Copy…</button><button id="swapUnit">Swap…</button></div><p class="muted">Project sound references keep their slot numbers. Copy/swap can change the sounds used by other projects. Individual delete/move-to-empty is not supported by this firmware.</p></section><section class="panel"><h2>Unit projects</h2><select id="unitProject" aria-label="Unit project slot">${Array.from({length:16},(_,i)=>option(i,'Project '+String(i).padStart(2,'0')+(unitProjects?' · '+(unitProjects[i]?.name||'Empty'):''),0)).join('')}</select><div class="bar"><button id="pullProject">Add project to Library</button><button id="loadProject">Load on unit…</button><button id="saveProject">Save current unit project…</button></div><p class="muted">Library titles are independent of the project’s working instrument name. Native project files contain references to instrument slots, not four embedded sound copies.</p></section></div><section class="panel"><h2>Send a Library item</h2><div class="bar"><select id="transferItem" aria-label="Library item to send">${itemOptions()}</select><button id="sendLibrary" class="primary" ${catalog.slots.some(i=>!i.trashed)?'':'disabled'}>Review transfer…</button></div><p>Instruments go to the selected instrument slot above. Projects go to the selected project slot. This sends the project record only; embedded sounds remain in the Library until deployed individually to the referenced slots. ${help('projects')}</p></section><section class="panel"><details><summary>Reset instrument banks</summary><p>These change the instrument. Each reset backs up the affected bank first; PC banks and the Library stay intact.</p><div class="bar"><button data-unit-reset="reset_defaults">Reset Bank A</button><button data-unit-reset="reset_user">Reset Bank B</button><button data-unit-reset="clear_user" class="danger">Clear Bank B</button></div></details></section>`;
 $('#unitSlot').onchange=()=>{$('#unitName').value=unitSlots?.[Number($('#unitSlot').value)]?.name||'';};bind('#readUnit',async()=>{unitSlots=(await deviceJob({action:'catalog'})).slots;$('#connection').textContent='FMER connected';drawUnit();});bind('#readProjects',async()=>{unitProjects=(await deviceJob({action:'project_catalog'})).slots;$('#connection').textContent='FMER connected';drawUnit();});bind('#unitRecord',()=>deviceJob({action:'record',battery_telemetry:true}));bind('#unitRecordStop',()=>deviceJob({action:'stop_recording'}));bind('#batteryHistory',async()=>{const r=await deviceJob({action:'battery_history'});download('FMER-battery-history.json',JSON.stringify(r.battery_history,null,2));notify('Raw history downloaded. Reconnect before powering off to retain unplugged readings.');});
 for(const [id,project] of [['#pullInstrument',false],['#pullProject',true]])bind(id,async()=>{const slot=Number($(project?'#unitProject':'#unitSlot').value),r=await deviceJob({action:project?'project_pull':'pull',slot});const imported=await api('/api/work',{action:'import',raw:r.raw});catalog=await api('/api/catalog',{action:'add',revision:catalog.revision,kind:project?'project':'instrument',title:project?'Project '+String(slot).padStart(2,'0')+' · '+imported.entry.name:imported.entry.name,entry:imported.entry,collection:'From FM-1',notes:project?'Imported unit project; referenced instruments are not embedded. Keep a complete unit backup.':''});notify('Added to the local Library.');});
 for(const [id,action,selector] of [['#playInstrument','load','#unitSlot'],['#loadProject','project_load','#unitProject'],['#saveProject','project_save','#unitProject']])bind(id,async()=>{const slot=Number($(selector).value);if(await confirmAction('Apply unit action?',`${action} at ${action==='load'?unitLabel(slot):'Project '+slot}. Playback stops. Saving replaces that project; a prior copy is retained.`))await deviceJob({action,slot,...(action==='project_save'?{confirmation:'Save device project '+slot}:{})});});
 for(const [id,action] of [['#renameUnit','instrument_rename'],['#copyUnit','instrument_copy'],['#swapUnit','instrument_swap']])bind(id,async()=>{const slot=Number($('#unitSlot').value),destination=Number($('#unitDestination').value),name=$('#unitName').value.trim();if(await confirmAction('Change unit instruments?',`${action.replace('instrument_','')} ${unitLabel(slot)}${action==='instrument_rename'?' to '+name:' and '+unitLabel(destination)}. Playback stops; originals are backed up. Project references are not remapped. A multi-slot swap can stop partway if disconnected.`))await deviceJob({action,slot,confirmation:'Apply unit instrument change',...(action==='instrument_rename'?{name}:{destination})});});
 bind('#sendLibrary',async()=>{const item=catalog.slots.find(i=>i.id===$('#transferItem').value),project=item.kind==='project',slot=Number($(project?'#unitProject':'#unitSlot').value);if(await confirmAction('Send '+item.title+'?',`Replace ${project?'Project '+slot:unitLabel(slot)} on the unit. Playback stops; prior contents are backed up.${project?' Referenced instruments are NOT replaced by this action.':''}`))await deviceJob({action:project?'project_push':'push',slot,raw:item.entry.native,confirmation:(project?'Replace device project ':'Replace device slot ')+slot});});
 document.querySelectorAll('[data-unit-reset]').forEach(b=>b.onclick=run(async()=>{if(await confirmAction(b.textContent+' on the unit?', 'The affected unit bank is backed up, then replaced or cleared. Playback stops. The other bank and PC library remain intact.'))await deviceJob({action:b.dataset.unitReset,confirmation:({reset_defaults:"Reset to FMER Default",reset_user:"Reset User Bank",clear_user:"Clear User Bank"})[b.dataset.reset||b.dataset.unitReset]});}));
}
function drawBackups(){
 $('#content').innerHTML=`<div class="cards"><section class="panel"><h2>Local Library</h2><p>Export instruments, projects, metadata, Trash and the latest Undo state as a checksummed catalog file.</p><div class="bar"><button id="catalogBackup" class="primary">Export Library backup</button><button id="catalogRestore">Replace Library from backup…</button><button id="emptyTrash" class="danger">Empty Trash…</button></div><p class="muted">Import on the Library page merges copies instead. Restore here replaces this local catalog.</p></section><section class="panel"><h2>Complete FM-1 snapshot</h2><p>Read all128 instrument destinations,16 projects, working state and MIDI settings. Leave controls untouched until the read completes. This is musical data, not a dump of boot/calibration/firmware.</p><button id="unitBackup" class="primary">Back up unit…</button><button id="downloadUnitBackup" ${unitBackup?'':'disabled'}>Download last snapshot</button></section></div><section class="panel"><h2>Restore to the unit</h2><p>Choose a checksummed unit backup, review its scope, then confirm. A fresh destination backup is retained before the first write. ${help('backups')}</p><button id="chooseUnitBackup">Choose backup file…</button><div id="restorePreview">${restoreFile?`<p><strong>${restoreFile.plan.instruments} instruments ? ${restoreFile.plan.projects} projects</strong></p><p>${esc(restoreFile.plan.scope)}</p><p>${restoreFile.plan.empty_instruments} empty instrument slots and ${restoreFile.plan.empty_projects} empty project slots will be left unchanged.</p>`:'No restore file selected.'}</div><button id="restoreUnit" class="danger" ${restoreFile?'':'disabled'}>Restore populated slots…</button><p class="muted">Empty source slots leave destination contents unchanged. Restore is a sequence of verified writes, not one atomic transaction. A failed operation retains progress and does not retry automatically.</p></section>`;
 bind('#catalogBackup',async()=>jsonDownload('FMER-Library-backup.json',(await api('/api/catalog',{action:'backup'})).backup));bind('#catalogRestore',()=>chooseFile('.json',async f=>{const backup=JSON.parse(await f.text());if(await confirmAction('Replace local Library?','All current catalog items are replaced by the backup. Undo remains available. PC banks and unit remain unchanged.')){catalog=await api('/api/catalog',{action:'restore',revision:catalog.revision,backup,confirmation:'Replace Local Catalog'});notify('Local Library restored.');}}));bind('#emptyTrash',async()=>{if(await confirmAction('Empty Catalog Trash?','Remove trashed Library entries. Export a backup first to keep a durable copy. The latest operation remains undoable.')){catalog=await api('/api/catalog',{action:'purge',revision:catalog.revision,confirmation:'Empty Catalog Trash'});notify('Trash emptied.');}});bind('#unitBackup',async()=>{if(await confirmAction('Read a complete unit backup?','Keep keys and controls untouched for about two minutes. No onboard data is changed.')){const r=await deviceJob({action:'backup_all'});unitBackup=r.backup;jsonDownload('FMER-unit-backup.json',unitBackup);drawBackups();}});bind('#downloadUnitBackup',()=>jsonDownload('FMER-unit-backup.json',unitBackup));bind('#chooseUnitBackup',()=>chooseFile('.json',async f=>{const value=JSON.parse(await f.text());restoreFile={value,plan:await api('/api/restore-plan',value)};drawBackups();}));bind('#restoreUnit',async()=>{if(await confirmAction('Restore populated unit slots?',restoreFile.plan.scope+' '+restoreFile.plan.instruments+' instruments and '+restoreFile.plan.projects+' projects will be written. Keep power and USB connected.'))await deviceJob({action:'restore_all',backup:restoreFile.value,confirmation:'Restore populated unit slots'});});
}
function drawFirmware(){
 const bundled=bundledFirmware.find(x=>x.available);
 $('#content').innerHTML=`<section class="panel"><p class="eyebrow">OFFLINE FIRMWARE INSTALLATION</p><h2>Install FMER 735</h2><p>Install or reinstall FMER on your FM-1. The updater checks the memory layout and preserves compatible calibration and saved-data regions. ${help('firmware')}</p><div class="bar"><button id="bundledFirmware" class="primary" ${bundled?'':'disabled'}>Inspect included firmware</button><button id="chooseFirmware">Choose another package&hellip;</button><button id="goBackup">Backups</button><a href="https://github.com/Nacsez/FMER/releases" target="_blank" rel="noopener noreferrer">Download updates &nearr;</a></div><p class="muted">${bundled?esc(bundled.title)+' is included; no download is needed.':esc(bundledFirmware[0]?.error||'No compatible bundled package is available.')}</p><div id="firmwareReport">${inspection?`<dl><dt>Target</dt><dd>${esc(inspection.product)}</dd><dt>Compatibility</dt><dd>${esc(inspection.compatibility||'FM-1 with compatible memory layout')}</dd><dt>Ready for installation</dt><dd>${inspection.installable?'Ready for device compatibility check':'No'}</dd></dl><p>${esc(inspection.limitation)}</p><details><summary>Package checksum &amp; inspection</summary><pre>${esc(JSON.stringify(inspection,null,2))}</pre></details>`:'Inspect a package to review its compatibility.'}</div><div id="installLoadouts" class="panel"></div><button id="installFirmware" ${inspection?.installable?'':'disabled'} class="danger">Install firmware&hellip;</button></section><section class="panel"><h2>Updates and compatible firmware</h2><p>Download a firmware package from GitHub, then choose it above. Custom applications are accepted only with the reviewed FMER 935 updater and the same protected memory layout. This is a transport check, not certification of the application. Other updaters and layouts need their publisher's installer; there is no force-flash option.</p><p>To update Companion, quit this copy, extract the new Windows ZIP into a new folder, and launch FMER Companion.exe. Your Library stays in your Windows user profile. Downloads require internet; installing, editing and Help work offline.</p></section><section class="panel"><h2>Before you connect</h2><ol><li>Connect only the FM-1 you want to install. Power it on and close music apps that use its MIDI ports.</li><li>Back up saved FMER instruments and projects before reinstalling. Stock firmware does not expose this backup interface.</li><li>Keep power and USB connected until completion. Initial FMER storage uses the included defaults.</li></ol><p>Different application versions are accepted when layout and calibration match. Unknown layouts are reported before application writing. If a transfer stops in this updater, reconnect and install the same included firmware to resume if compatibility can still be verified. A damaged bootloader or another updater may require a separate recovery procedure.</p><details><summary>Stock firmware, backups and recovery</summary><p>Normal stock USB MIDI does not provide a verified full-backup or patch-readback command. Stock ROM backup requires a separate recovery-mode procedure and administrator access. A full ROM backup can contain recoverable patches, but it is not an FMER project backup.</p><p>Restore Original Firmware below installs a supported user-provided V15 image. It preserves device identity and calibration; it does not recreate original user settings. Keep your own verified original backup; never restore another instrument’s complete ROM, which includes its identity and calibration. No stock ROM or proprietary patch bank is bundled. See Help for the current recovery limits.</p></details><p class="muted">This application runs entirely on this PC; no account, hosted page or separate Python installation is required.</p></section>`;
 $('#content').insertAdjacentHTML('beforeend',`<section class="panel"><h2>Restore Original Firmware</h2><p>Choose your supported stock V15 ROM backup or firmware image. We do not bundle proprietary stock firmware. This restores the application, not an exact factory-settings snapshot. Back up FMER sounds and projects first. Unknown layouts remain blocked.</p><button id="chooseStock">Choose original firmware file&hellip;</button></section>`);
 bind('#chooseStock',()=>chooseFile('.bin,.fwsc',async f=>{const bytes=new Uint8Array(await f.arrayBuffer());let raw='';for(let i=0;i<bytes.length;i+=8192)raw+=String.fromCharCode(...bytes.subarray(i,i+8192));inspection=await api('/api/firmware',{action:'inspect_stock',raw:btoa(raw)});drawFirmware();notify(inspection.installable?'Original V15 verified. Use Install firmware above to restore it. This does not reset saved settings.':inspection.limitation||'This firmware requires a separately tested migration and cannot be installed here.');}));
 bind('#bundledFirmware',async()=>{inspection=await api('/api/firmware',{action:'inspect',release:bundled.id});drawFirmware();});
 bind('#chooseFirmware',()=>chooseFile('.fwsc',async f=>{const bytes=new Uint8Array(await f.arrayBuffer());let raw='';for(let i=0;i<bytes.length;i+=8192)raw+=String.fromCharCode(...bytes.subarray(i,i+8192));inspection=await api('/api/firmware',{action:'inspect',raw:btoa(raw)});drawFirmware();}));
 bind('#goBackup',()=>changeView('backups'));
 bind('#installFirmware',installWithLoadout);drawInstallLoadouts().catch(fail);
}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=run(async()=>{if(b.dataset.view==='banks')banks=await api('/api/banks');changeView(b.dataset.view);}));
(async()=>{try{await refresh();await fetchUnits();const c=await api('/api/capabilities');bundledFirmware=c.bundled_firmware||[];$('#platform').textContent=c.device_transport;changeView(['library','banks','editor','unit','backups','firmware','loadouts','units','feedback'].includes(location.hash.slice(1))?location.hash.slice(1):'library');window.FMERStartup.ready();const pending=sessionStorage.getItem('fmerJob');if(pending)await waitJob(pending);}catch(e){fail(e);window.FMERStartup.fail('initialization_error',e);}})();

bind('#downloadJob',()=>{if(lastJob)jsonDownload('FMER-operation-'+lastJob.id+'.json',lastJob);});

bind('#quitApp',async()=>{if(await confirmAction('Quit companion?','This stops diagnostic capture and releases MIDI. Save or export unsaved editor work first.')){await api('/api/quit',{});notify('Companion stopped. You can close this tab.');document.querySelectorAll('button').forEach(b=>b.disabled=true);}});

// Enumeration observes attachment without acquiring MIDI or interrupting a DAW.
let previousPorts=null;
function invalidateUnit(label){unitSlots=null;unitProjects=null;$('#connection').textContent=label; if(view==='unit'&&!activeJob)drawUnit();}
async function pollPresence(){
 if(activeJob)return;
 try{const p=await api('/api/presence'),signature=JSON.stringify(p),present=p.inputs.length&&p.outputs.length;
 if(p.inputs.length>1||p.outputs.length>1){
  if($('#connection').textContent!=='Multiple FM-1s - connect one')invalidateUnit('Multiple FM-1s - connect one');
  previousPorts=signature;return;
 }
 if(previousPorts!==null&&signature!==previousPorts)invalidateUnit(present?'FM-1 detected - check connection':'Not connected');
 if(!present&&$('#connection').textContent!=='Not connected')invalidateUnit('Not connected');
 previousPorts=signature;
 }catch(e){if($('#connection').textContent!=='Connection status unavailable')invalidateUnit('Connection status unavailable');}
}
const browserTab=crypto.randomUUID();
const heartbeat=()=>api('/api/browser',{tab:browserTab}).catch(()=>{});
heartbeat();setInterval(heartbeat,10000);setInterval(pollPresence,3000);
addEventListener('pagehide',()=>navigator.sendBeacon('/api/browser',JSON.stringify({tab:browserTab,closed:true})));
addEventListener('pageshow',heartbeat);

function drawFeedback(){
 const areas=['Companion usability','Firmware installation','FMER usability','Menus and navigation','Sounds and options','Effects','Arpeggiator','Sequencer','4T / 6V / 1V modes','MIDI connectivity','Other'];
 $('#content').innerHTML=`<section class="panel"><h2>Tell us what you tested</h2><p>Every field is optional. Describe what you expected, what happened, and steps to reproduce. Leave untested areas blank. Feedback is downloaded locally; nothing is sent automatically. Submit it through the repository issue form or share it with the maintainer. Code contributions are currently reserved; please use issues, not pull requests.</p><label>Computer, unit and starting firmware<input id="testContext" maxlength="1000" placeholder="Windows 11; FM-1; stock V15"></label>${areas.map((a,i)=>`<label>${esc(a)}<textarea id="feedback${i}" rows="3" maxlength="6000" placeholder="Optional"></textarea></label>`).join('')}<button id="feedbackExport" class="primary">Export feedback and diagnostic summary</button><p>Includes up to30 recent operation summaries. Excludes sounds, projects, raw device data and local paths. Review the downloaded file before sharing.</p></section>`;
 bind('#feedbackExport',async()=>{const report=await api('/api/support');report.context=$('#testContext').value;report.feedback=Object.fromEntries(areas.map((a,i)=>[a,$('#feedback'+i).value]).filter(x=>x[1].trim()));jsonDownload('FMER-beta-feedback.json',report);notify('Feedback exported locally. Attach it to a GitHub issue or share it with the maintainer.');});
}

bind('#downloadJobBackup',async()=>{if(lastJob)jsonDownload('FMER-pre-transfer-backup.fmer-backup.json',await api('/api/jobs/'+lastJob.id+'/backup'));});

async function acceptSoundPack(result){
 const existing=new Set(catalog.slots.filter(i=>!i.trashed).map(i=>i.notes+'|'+i.entry.native));
 const incoming=result.catalog.payload.slots.filter(i=>!existing.has(i.notes+'|'+i.entry.native));
 if(!incoming.length){notify('These sounds are already in your Library.');return;}
 if(!await confirmAction(`Add ${incoming.length} instruments to Library?`,result.losses.join(' ')+' Existing sounds and the connected unit are unchanged.'))return;
 // Preserve the server-checked envelope; imports are a single Undo transaction.
 // When some entries already exist, import the full pack only after explicit review.
 if(incoming.length!==result.count && !await confirmAction('Some sounds already exist',`Importing the complete pack adds ${result.count} copies, including ${result.count-incoming.length} duplicates. Continue?`))return;
 await mutate('import',{backup:result.catalog});collection=result.catalog.payload.slots[0].collection;kind='instrument';query='';trash=false;drawLibrary();notify(`Added ${result.count} instruments. Unit unchanged.`);
}
function drawSoundSources(){
 $('#content').innerHTML=`<div class="bar"><button id="backLibrary">Back to Library</button>${help('community')}</div><h2>Included sounds</h2><p>Add editable copies to Library, then audition or send chosen instruments to the unit.</p><div class="bar"><button id="addDefaults">FMER Defaults &middot; 64</button><button id="addOEM">OEM Patches &middot; V15 &middot; 128</button></div><p>OEM Patches keeps the original names and slot numbers. Eleven voices need range normalization; Notes records each change. FM voice data is included, not stock effects or sequences.</p><h2>Read from another firmware</h2><p>Connect one Felucca, SLOOP or JIANT unit. Read its available FM6 voices without replacing firmware or changing presets. This protocol-tested reader still awaits a physical round-trip qualification. Other engines, projects and Felucca/JIANT separate voice cartridges are not captured.</p><div class="bar"><button id="captureCommunity">Read community FM voices&hellip;</button><button id="importCommunity">Import FM voice capture&hellip;</button></div><p>Stock V15 has no qualified live patch-read command. Use the included OEM bank for its original sounds; a full ROM backup is a separate recovery operation.</p>`;
 bind('#backLibrary',drawLibrary);
 bind('#addDefaults',async()=>acceptSoundPack(await api('/api/sound-packs',{id:'fmer-defaults'})));
 bind('#addOEM',async()=>acceptSoundPack(await api('/api/sound-packs',{id:'oem-v15'})));
 bind('#importCommunity',()=>chooseFile('.json',async f=>acceptSoundPack(await api('/api/community-import',{archive:JSON.parse(await f.text())}))));
 bind('#captureCommunity',async()=>{
  if(!await confirmAction('Read available FM voices?', 'Leave the connected community unit untouched. This only reads FM voice data and saves a capture on this computer. It is not a full device backup.'))return;
  const result=await deviceJob({action:'community_capture'});
  jsonDownload('Community-FM6-capture.json',result.archive);
  await acceptSoundPack(result);
 });
}
